// Optional English Markdown is linked to its Japanese article by Gatsby.
// Identity, canonical URL, and publication date always come from index.md.
export const localizePost = (post, locale) => {
  const translation = post?.english
  if (!post || locale !== "en" || !translation) return post
  return {
    ...post,
    html: translation.html ?? post.html,
    excerpt: translation.excerpt ?? post.excerpt,
    frontmatter: {
      ...post.frontmatter,
      title: translation.frontmatter?.title || post.frontmatter.title,
      description:
        translation.frontmatter?.description?.trim() ||
        translation.excerpt ||
        post.frontmatter.description,
    },
  }
}
